public sealed class MgaWholesalerRepository : IMgaWholesalerRepository
{
    private readonly ISqlConnectionFactory _cf;
    public MgaWholesalerRepository(ISqlConnectionFactory cf) => _cf = cf;
    private const string Cols = "MgaWholesalerId, TenantId, MgaCode, MgaName, Type, Website, IsActive, SortOrder, CreatedDateUtc";
    public async Task<MgaWholesalerDto?> GetByIdAsync(Guid id, CancellationToken ct = default) { using var cn = await _cf.CreateOpenConnectionAsync(ct); return await cn.QuerySingleOrDefaultAsync<MgaWholesalerDto>(new CommandDefinition($"SELECT {Cols} FROM Agency.MgaWholesaler WHERE MgaWholesalerId=@Id AND IsDeleted=0;", new { Id = id }, cancellationToken: ct)); }
    public async Task<PagedResult<MgaWholesalerDto>> SearchAsync(Guid tenantId, string? searchTerm, int pageNumber = 1, int pageSize = 50, CancellationToken ct = default) { var sql = RepositorySql.BuildPagedSearchSql("Agency.MgaWholesaler", Cols, "MgaName LIKE '%'+@SearchTerm+'%' OR MgaCode LIKE '%'+@SearchTerm+'%'", "SortOrder ASC, MgaName ASC"); using var cn = await _cf.CreateOpenConnectionAsync(ct); using var multi = await cn.QueryMultipleAsync(new CommandDefinition(sql, new { TenantId = tenantId, SearchTerm = searchTerm ?? "", Offset = (Math.Max(pageNumber, 1) - 1) * pageSize, PageSize = pageSize }, cancellationToken: ct)); return new() { Items = (await multi.ReadAsync<MgaWholesalerDto>()).AsList(), TotalCount = await multi.ReadSingleAsync<int>(), PageNumber = pageNumber, PageSize = pageSize }; }
    public async Task<Guid> CreateAsync(CreateMgaWholesalerRequest r, CancellationToken ct = default) { const string sql = "INSERT INTO Agency.MgaWholesaler (MgaWholesalerId,TenantId,MgaCode,MgaName,Type,Website,SortOrder,IsActive,IsDeleted,CreatedDateUtc) VALUES (@Id,@TenantId,@MgaCode,@MgaName,@Type,@Website,@SortOrder,1,0,GETUTCDATE());"; var id = Guid.NewGuid(); using var cn = await _cf.CreateOpenConnectionAsync(ct); await cn.ExecuteAsync(new CommandDefinition(sql, new { Id = id, r.TenantId, r.MgaCode, r.MgaName, r.Type, r.Website, r.SortOrder }, cancellationToken: ct)); return id; }
    public async Task UpdateAsync(Guid id, UpdateMgaWholesalerRequest r, CancellationToken ct = default) { const string sql = "UPDATE Agency.MgaWholesaler SET MgaCode=@MgaCode,MgaName=@MgaName,Type=@Type,Website=@Website,IsActive=@IsActive,SortOrder=@SortOrder,ModifiedDateUtc=GETUTCDATE() WHERE MgaWholesalerId=@Id AND IsDeleted=0;"; using var cn = await _cf.CreateOpenConnectionAsync(ct); await cn.ExecuteAsync(new CommandDefinition(sql, new { Id = id, r.MgaCode, r.MgaName, r.Type, r.Website, r.IsActive, r.SortOrder }, cancellationToken: ct)); }
    public async Task DeleteAsync(Guid id, CancellationToken ct = default) { using var cn = await _cf.CreateOpenConnectionAsync(ct); await cn.ExecuteAsync(new CommandDefinition("UPDATE Agency.MgaWholesaler SET IsDeleted=1 WHERE MgaWholesalerId=@Id;", new { Id = id }, cancellationToken: ct)); }
}

